!function(){"use strict";function entidadLogoCtrl($scope,mS,tS){let accion=JSON.parse(localStorage.getItem("accion"));null===accion?location.href="/Home/Index":$scope.accion=accion[0];var url="/EntidadLogo/";$scope.logo={},$scope.entidades=[],$scope.logos=[],$scope.tipoOperacion=0,$scope.file="",$scope.openModal=function(data=null,type){if($scope.tipoOperacion=type,1!=type){if(2==type){$scope.logo=data;let blob=new Blob([data.imagen],{type:data.mimeType}),file=new File([blob],data.nombreImagen);return $scope.file=file,void $("#logoModal").modal("show")}}else $("#logoModal").modal("show")},$scope.initialLoad=function(){mS.getData("get","/Entidad/OptionEntidad").then((function(response){$scope.entidades=response.data}),error=>console.log(error)),mS.getData("get",url+"Get").then((function(response){0!=response.id?$scope.logos=response.data:tS.toastr("warning",response.message,response.titleSms)}),error=>console.log(error))},$scope.initialLoad(),$scope.save=function(){let method=1===$scope.tipoOperacion?"Post":"Put",file=$scope.file;null!=file&&null!=file?mS.getDataFile(url+method,file,$scope.logo).then((function(response){if(0!=response.id)return 1==response.id?($scope.logo={},$scope.initialLoad(),$("#logoModal").modal("hide"),void tS.toastr("success",response.message,response.titleSms)):void 0;tS.toastr("warning",response.message,response.titleSms)}),error=>console.log(error)):tS.toastr("warning","Por favor suba el archivo del logo")},$scope.put=function(){mS.getData("put",url+"Put",$scope.logo).then((function(response){if(0!=response.id)return 1==response.id?($scope.logo={},$scope.initialLoad(),$("#modalUpdate").modal("hide"),void tS.toastr("success",response.message,response.titleSms)):void 0;tS.toastr("warning",response.message,response.titleSms)}),error=>console.log(error))},$scope.askToDelete=function(item){Swal.fire({icon:"warning",text:"Esta seguro/a de eliminar este logo ahora?",showDenyButton:!0,confirmButtonText:"Si",denyButtonText:"No",allowOutsideClick:!1}).then(result=>{result.isConfirmed&&$scope.delete(item)})},$scope.delete=function(item){mS.getData("delete",url+"Delete?id="+item.logo.idEntidadLogo).then(response=>{if(0!=response.id)return 1==response.id?($scope.initialLoad(),$("#logoModal").modal("hide"),void tS.toastr("success",response.message,response.titleSms)):void 0;tS.toastr("warning",response.message,response.titleSms)},error=>console.log(error))}}angular.module("acontPlusApp").controller("entidadLogoCtrl",entidadLogoCtrl),entidadLogoCtrl.$inject=["$scope","mainService","toastService"]}(window.angular);